      {
        "factor": "Large margin of Lamag victory (BN majority 5,681)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "A wide win reduces plausible grounds for reversal and lessens likelihood that petition grounds will prove ballots illicit or counts incorrect."
      },
      {
        "factor": "Historical rarity of overturns in Sabah/Malaysia elections",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Only a handful of overturns exist; indicates low base rate for reversal even with petitions."
      },
      {
        "factor": "Independent petition possibility for Lamag by-election",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Public signals of intent to petition raise nonzero risk if grounds emerge."
      },
      {
        "factor": "Ongoing Sabah election petitions following 2025 polls",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Environment of petitions creates potential for challenge, though not strongly evidenced for Lamag specifically."
      },
      {
        "factor": "No credible irregularities reported in Lamag results as of May 1, 2026",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Lack of irregularities reduces probability of reversal, but does not prove innocence of any grounds."
      }
    ],
    "synthesis_rationale": "The posterior is the result of aggregating downward updates from margin and historical rarity with modest upward pressure from petition talk. Given correlation across petition-related factors, a conservative adjustment yields a low posterior (1%). Range reflects calibration uncertainty and limited public signals."
  }
}

